<?php $e=fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');?>
<div class="section-heading"><div><div class="eyebrow">Prospecção e indicações</div><h1>E-mail marketing</h1><p class="text-secondary mb-0">Campanhas, contatos e origem das conversões em um só lugar.</p></div><a class="btn btn-light" href="/master/email-marketing/exportar">Exportar CSV</a></div>
<?php if(isset($_GET['smtp'])||isset($_GET['smtp_test'])||isset($_GET['leads'])||isset($_GET['campaign'])):?><div class="alert alert-success"><?=isset($_GET['campaign'])?'Campanha adicionada à fila.':(isset($_GET['smtp_test'])?'E-mail de teste enviado.':(isset($_GET['smtp'])?'SMTP salvo com segurança.':(int)$_GET['leads'].' contato(s) processado(s).'))?></div><?php endif;?>
