<div class="row g-3 mb-4"><?php foreach([['Contatos ativos',$stats['active']],['Descadastrados',$stats['unsubscribed']],['E-mails enviados',$stats['sent']],['Falhas',$stats['failed']]] as $m):?><div class="col-6 col-xl-3"><div class="card metric-card h-100"><div class="card-body"><div class="metric-label"><?=$m[0]?></div><div class="metric-value"><?=(int)$m[1]?></div></div></div></div><?php endforeach;?></div>

<div class="card mb-4"><div class="card-header"><strong>Desempenho das indicações</strong><small class="d-block text-secondary">O clique é atribuído por 30 dias; a conversão ocorre quando o estabelecimento conclui o cadastro.</small></div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Indicador</th><th>Perfil</th><th>Código</th><th>Cliques</th><th>Cadastros</th><th>Conversão</th></tr></thead><tbody><?php foreach($staff as $person):$rate=(int)$person['clicks']>0?((int)$person['conversions']/(int)$person['clicks']*100):0;?><tr><td><strong><?=$e($person['name'])?></strong><small class="d-block text-secondary"><?=$e($person['email'])?></small></td><td><?=$person['role_slug']==='master'?'Master':'Suporte'?></td><td><code><?=$e($person['referral_code'])?></code></td><td><?=(int)$person['clicks']?></td><td><?=(int)$person['conversions']?></td><td><?=number_format($rate,1,',','.')?>%</td></tr><?php endforeach;?><?php if(!$staff):?><tr><td colspan="6"><div class="empty-state">Nenhum indicador disponível.</div></td></tr><?php endif;?></tbody></table></div></div>

<div class="card mb-4"><div class="card-header d-flex justify-content-between"><div><strong>SMTP exclusivo para marketing</strong><small class="d-block text-secondary">Não altera o SMTP transacional.</small></div><span class="badge <?=$smtpConfigured?'text-bg-success':'text-bg-warning'?>"><?=$smtpConfigured?'Configurado':'Pendente'?></span></div><div class="card-body"><form method="post" action="/master/email-marketing/smtp" class="row g-3"><?=\App\Core\CSRF::field()?><div class="col-md-4"><label class="form-label">Nome do remetente</label><input class="form-control" name="from_name" required value="<?=$e($smtp['from_name']??'ApPlanner')?>"></div><div class="col-md-4"><label class="form-label">E-mail remetente</label><input class="form-control" type="email" name="from_email" required value="<?=$e($smtp['from_email']??'')?>"></div><div class="col-md-4"><label class="form-label">Responder para</label><input class="form-control" type="email" name="reply_to" value="<?=$e($smtp['reply_to']??'')?>"></div><div class="col-md-4"><label class="form-label">Servidor SMTP</label><input class="form-control" name="host" required value="<?=$e($smtp['host']??'')?>" placeholder="mail.applanner.com.br"></div><div class="col-md-2"><label class="form-label">Porta</label><input class="form-control" type="number" name="port" min="1" max="65535" value="<?=(int)($smtp['port']??587)?>"></div><div class="col-md-2"><label class="form-label">Segurança</label><select class="form-select" name="encryption"><?php foreach(['tls'=>'TLS','ssl'=>'SSL','none'=>'Nenhuma'] as $v=>$l):?><option value="<?=$v?>" <?=($smtp['encryption']??'tls')===$v?'selected':''?>><?=$l?></option><?php endforeach;?></select></div><div class="col-md-4"><label class="form-label">Usuário</label><input class="form-control" name="username" value="<?=$e($smtp['username']??'')?>"></div><div class="col-md-4"><label class="form-label">Senha</label><input class="form-control" type="password" name="password" autocomplete="new-password"><small class="text-secondary"><?=$smtpConfigured?'Em branco mantém a senha atual.':'Informe a senha SMTP.'?></small></div><div class="col-12"><button class="btn btn-primary">Salvar SMTP</button></div></form><?php if($smtpConfigured):?><hr><form method="post" action="/master/email-marketing/smtp/testar" class="row g-2 align-items-end"><?=\App\Core\CSRF::field()?><div class="col-md-5"><label class="form-label">Enviar teste para</label><input class="form-control" type="email" name="test_email" required></div><div class="col-md-3"><button class="btn btn-outline-primary w-100">Testar SMTP</button></div></form><?php endif;?></div></div>

<div class="row g-4 mb-4"><div class="col-xl-7"><div class="card h-100"><div class="card-header"><strong>Nova campanha</strong></div><div class="card-body"><form method="post" action="/master/email-marketing/enviar" data-warn-unsaved><?=\App\Core\CSRF::field()?><label class="form-label">Responsável pela indicação</label><select class="form-select mb-3" name="referrer_user_id" required><option value="">Selecione Master ou Suporte</option><?php foreach($staff as $person):?><option value="<?=(int)$person['id']?>"><?=$e($person['name'])?> · <?=$person['role_slug']==='master'?'Master':'Suporte'?></option><?php endforeach;?></select><div class="form-text mb-3">O link individual desta pessoa será inserido automaticamente em cada e-mail.</div><label class="form-label">Assunto</label><input class="form-control mb-3" name="subject" maxlength="190" required><label class="form-label">Mensagem</label><textarea class="form-control" name="body" rows="11" required placeholder="Olá {nome},&#10;&#10;Conheça o ApPlanner..."></textarea><div class="form-text">Variáveis: <code>{nome}</code>, <code>{email}</code> e <code>{link_indicacao}</code>. Mesmo sem usar a última variável, o link será acrescentado ao final.</div><div class="alert alert-warning mt-3">Será enviado para <?=(int)$stats['active']?> contatos ativos. Utilize somente uma base legal válida.</div><button class="btn btn-primary" <?=$smtpConfigured&&$stats['active']>0&&$staff?'':'disabled'?>>Colocar campanha na fila</button></form></div></div></div>
<div class="col-xl-5"><div class="card h-100"><div class="card-header"><strong>Adicionar contatos</strong></div><div class="card-body"><form method="post" action="/master/email-marketing/contatos" class="row g-2 mb-4"><?=\App\Core\CSRF::field()?><div class="col-sm-5"><input class="form-control" name="name" placeholder="Nome" required></div><div class="col-sm-5"><input class="form-control" type="email" name="email" placeholder="E-mail" required></div><div class="col-sm-2"><button class="btn btn-primary w-100">+</button></div></form><form method="post" action="/master/email-marketing/lista" class="mb-4"><?=\App\Core\CSRF::field()?><label class="form-label">Colar lista</label><textarea class="form-control" name="list" rows="6" placeholder="Maria,maria@empresa.com&#10;João;joao@empresa.com"></textarea><button class="btn btn-outline-primary mt-2">Cadastrar lista</button></form><form method="post" enctype="multipart/form-data" action="/master/email-marketing/importar"><?=\App\Core\CSRF::field()?><label class="form-label">Importar CSV</label><input class="form-control" type="file" name="csv" accept=".csv,text/csv" required><div class="form-text">Formato nome,email ou nome;email. Até 5 MB/5.000 linhas.</div><button class="btn btn-outline-primary mt-2">Importar CSV</button></form></div></div></div></div>

<div class="card mb-4"><div class="card-header"><strong>Campanhas</strong></div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Campanha</th><th>Indicador</th><th>Status</th><th>Total</th><th>Enviados</th><th>Falhas</th></tr></thead><tbody><?php foreach($campaigns as $c):?><tr><td><strong><?=$e($c['subject'])?></strong><small class="d-block text-secondary"><?=$e($c['created_at'])?></small></td><td><?=$e($c['referrer_name']??'—')?></td><td><?=$e(['queued'=>'Na fila','sending'=>'Enviando','completed'=>'Concluída','cancelled'=>'Cancelada'][$c['status']]??$c['status'])?></td><td><?=(int)$c['total_count']?></td><td><?=(int)$c['sent_count']?></td><td><?=(int)$c['failed_count']?></td></tr><?php endforeach;?><?php if(!$campaigns):?><tr><td colspan="6"><div class="empty-state">Nenhuma campanha.</div></td></tr><?php endif;?></tbody></table></div></div>

<div class="card"><div class="card-header"><strong>Base de contatos</strong></div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Nome</th><th>E-mail</th><th>Origem</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($leads as $lead):?><tr><td><?=$e($lead['name'])?></td><td><?=$e($lead['email'])?></td><td><?=$e($lead['source'])?></td><td><?=$e(['active'=>'Ativo','unsubscribed'=>'Descadastrado','bounced'=>'Rejeitado'][$lead['status']]??$lead['status'])?></td><td><form method="post" action="/master/email-marketing/contatos/<?=(int)$lead['id']?>"><?=\App\Core\CSRF::field()?><select class="form-select form-select-sm" name="status" onchange="this.form.submit()"><option value="active" <?=$lead['status']==='active'?'selected':''?>>Ativo</option><option value="unsubscribed" <?=$lead['status']==='unsubscribed'?'selected':''?>>Descadastrado</option><option value="bounced" <?=$lead['status']==='bounced'?'selected':''?>>Rejeitado</option></select></form></td></tr><?php endforeach;?><?php if(!$leads):?><tr><td colspan="5"><div class="empty-state">Nenhum contato.</div></td></tr><?php endif;?></tbody></table></div></div>
